using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Threading;
using Ivad.Ids;
namespace Ivad.Annotator {
 public sealed partial class MainWindow {
  internal static int HotfixChild(string root,string ready,string mode){
   var s=new Store(root);var f=s.Data.entities.First(e=>e.kind=="Frame");
   if(mode=="pre")Work.Configure(()=>false,message=>{if(message=="HOTFIX_COMMIT_PRE_REPLACE"){File.WriteAllText(ready,"pre");System.Threading.Thread.Sleep(30000);}});
   s.ReviewCurrent(f.id,"unknown","unknown","owned-child");
   File.WriteAllText(ready,Codec.Fingerprint(s.Data));if(mode=="post")System.Threading.Thread.Sleep(30000);return 0;
  }
  static System.Diagnostics.Process StartHotfixChild(string root,string ready,string mode){
   var info=new System.Diagnostics.ProcessStartInfo(System.Reflection.Assembly.GetEntryAssembly().Location,"--hotfix-child \""+root+"\" \""+ready+"\" "+mode){UseShellExecute=false,CreateNoWindow=true,WindowStyle=System.Diagnostics.ProcessWindowStyle.Hidden,WorkingDirectory=Path.GetDirectoryName(root)};
   var p=System.Diagnostics.Process.Start(info);File.AppendAllText(Path.Combine(Path.GetDirectoryName(ready),"owned-children.jsonl"),Codec.Json(new{pid=p.Id,exe=info.FileName,root=root,mode=mode})+Environment.NewLine);p.PriorityClass=System.Diagnostics.ProcessPriorityClass.BelowNormal;return p;
  }
  public int HotfixAcceptance(string output){
   System.Threading.SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher));
   System.Diagnostics.Process.GetCurrentProcess().PriorityClass=System.Diagnostics.ProcessPriorityClass.BelowNormal;
   Directory.CreateDirectory(output);var results=new List<object>();int failed=0;
   Action<string,Action> test=(name,work)=>{try{work();results.Add(new{name=name,status="PASS",scope="actual filesystem / in-process WPF; no physical input"});}catch(Exception e){failed++;results.Add(new{name=name,status="FAIL",error=e.ToString()});}File.WriteAllText(Path.Combine(output,"results.json"),Codec.Json(new{failed=failed,tests=results}));};
   Store s=Fixture(Path.Combine(output,"project"),24);string root=s.Root;
   Func<Store> reopen=()=>new Store(root);
   Func<string[]> empty=()=>s.Data.entities.Where(e=>e.kind=="Frame"&&e.Text("state")=="unannotated").Select(e=>e.id).ToArray();
   test("fast-review-roundtrip-and-fingerprint",()=>{string id=empty()[0];s.ReviewCurrent(id,"normal","confirmed","hotfix");var disk=reopen();Check(Codec.Fingerprint(s.Data)==Codec.Fingerprint(disk.Data),"identical document / sequence / UUID / audit");Check(disk.Find(id).revision==2&&disk.Find(id).Text("state")=="normal","frame state");});
   test("local-geometry-add-edit-delete-validation-and-rollback",()=>{string id=empty().Last();string fault=s.Data.entities.First(e=>e.kind=="Fault").id;var geometry=s.AddGeometryCurrent(id,fault,"box",new[]{1.0,1,20,20},false);Check(Codec.Fingerprint(s.Data)==Codec.Fingerprint(reopen().Data),"local geometry roundtrip");Work.ResetMetrics();s.EditGeometryCurrent(geometry.id,new[]{2.0,2,21,21},"hotfix",false);Check(Work.HashCalls==1,"edit only conflict manifest hash, cached current asset");string before=Codec.Fingerprint(s.Data);bool rejected=false;try{s.EditGeometryCurrent(geometry.id,new[]{-1.0,1,20,20},"hotfix",false);}catch(InvalidDataException){rejected=true;}Check(rejected&&before==Codec.Fingerprint(s.Data)&&before==Codec.Fingerprint(reopen().Data),"local validation rollback");s.EditGeometryCurrent(geometry.id,null,"hotfix",true);Check(reopen().Find(geometry.id).Text("deleted")=="True","soft deletion persisted");});
   test("batch-three-single-commit-zero-image-sha",()=>{var ids=empty().Take(3).ToArray();long seq=s.Data.sequence;Work.ResetMetrics();batchUndo=s.MarkNormalBatch(ids,"hotfix");Check(s.Data.sequence==seq+1&&ids.All(id=>s.Find(id).Text("state")=="normal"),"one transaction");Check(Work.HashCalls==1,"only manifest conflict hash, no image hash");Check(Codec.Fingerprint(s.Data)==Codec.Fingerprint(reopen().Data),"disk equivalence");});
   test("undo-restores-frame-state-reviews-and-revisions",()=>{var before=s.Data.entities.Where(e=>e.kind=="Frame").Select(e=>e.id).ToArray();Work.ResetMetrics();s.UndoBatch(batchUndo,"hotfix");Check(Work.HashCalls==1,"undo only hashes manifest, not images");Check(s.Data.entities.Count(e=>e.kind=="Review")==1,"batch reviews removed");Check(s.Data.entities.Where(e=>before.Contains(e.id)&&e.Text("state")=="unannotated").Count()==23,"prior frame states restored");Check(Codec.Fingerprint(s.Data)==Codec.Fingerprint(reopen().Data),"reopen equivalence");});
   test("batch-invalid-id-and-anomaly-all-or-nothing",()=>{string a=empty()[0],b=empty()[1];s.AddAnnotation(b,s.Data.entities.First(e=>e.kind=="Fault").id,"box",new[]{1.0,1,20,20},false);string before=Codec.Fingerprint(s.Data);bool rejected=false;try{s.MarkNormalBatch(new[]{a,b},"hotfix");}catch{rejected=true;}Check(rejected&&before==Codec.Fingerprint(s.Data)&&before==Codec.Fingerprint(reopen().Data),"anomaly protected / entire batch unchanged");rejected=false;try{s.MarkNormalBatch(new[]{a,Guid.NewGuid().ToString()},"hotfix");}catch{rejected=true;}Check(rejected&&before==Codec.Fingerprint(s.Data),"invalid UUID rollback");});
   test("confirmed-abnormal-and-inconsistent-review-protected",()=>{string id=empty()[2],other=empty()[3];s.ReviewCurrent(id,"abnormal","confirmed","hotfix");string before=Codec.Fingerprint(s.Data);bool rejected=false;try{s.MarkNormalBatch(new[]{id,other},"hotfix");}catch{rejected=true;}Check(rejected&&before==Codec.Fingerprint(s.Data),"confirmed abnormal protected");});
   test("cancelled-batch-restores-memory-and-disk",()=>{string id=empty()[4],before=Codec.Fingerprint(s.Data);bool rejected=false;Work.Configure(()=>true,null);try{s.MarkNormalBatch(new[]{id},"hotfix");}catch(OperationCanceledException){rejected=true;}finally{Work.Configure(null,null);}Check(rejected&&before==Codec.Fingerprint(s.Data)&&before==Codec.Fingerprint(reopen().Data),"cancel rollback");});
   test("conflict-two-independent-sessions-reject-stale-review",()=>{var stale=reopen();string id=empty()[5];s.ReviewCurrent(id,"normal","confirmed","writer-1");string committed=Codec.Fingerprint(s.Data);bool rejected=false;try{stale.ReviewCurrent(empty()[6],"normal","confirmed","writer-2");}catch(IOException){rejected=true;}Check(rejected&&committed==Codec.Fingerprint(reopen().Data),"stale session rejected");});
   test("undo-rejects-subsequent-edits",()=>{var eligible=empty().Where(candidate=>!s.Data.entities.Any(e=>e.kind=="Annotation"&&e.Text("frame_id")==candidate)).ToArray();var undo=s.MarkNormalBatch(new[]{eligible[0]},"hotfix");s.ReviewCurrent(eligible[1],"normal","confirmed","later");string before=Codec.Fingerprint(s.Data);bool rejected=false;try{s.UndoBatch(undo,"hotfix");}catch(IOException){rejected=true;}Check(rejected&&before==Codec.Fingerprint(s.Data),"later edits retained");});
   test("ui-video-status-filters-and-draft-retention",()=>{Use(s);Navigate("标注与审核");Check(frames.SelectionMode==SelectionMode.Extended&&VirtualizingStackPanel.GetIsVirtualizing(frames),"native extended selection and virtualization");frameVideoFilter.SelectedIndex=1;string video=((Choice)frameVideoFilter.SelectedItem).Id;Check(frames.Items.Cast<Choice>().All(c=>s.Find(c.Id).Text("video_id")==video),"single video");frameVideoFilter.SelectedIndex=0;frameStateFilter.SelectedIndex=2;Check(frames.Items.Count>0&&frames.Items.Cast<Choice>().All(c=>LatestReview(c.Id).Text("status")=="confirmed"),"confirmed editable");var id=frame.id;polygon.Add(new Point(1,1));int old=frameStateFilter.SelectedIndex;frameStateFilter.SelectedIndex=1;Check(frameStateFilter.SelectedIndex==old&&frame.id==id&&polygon.Count==1,"filter keeps draft");polygon.Clear();frameStateFilter.SelectedIndex=0;});
   test("ui-programmatic-multiselect-batch-and-undo",()=>{var eligible=empty().Where(candidate=>!s.Data.entities.Any(e=>e.kind=="Annotation"&&e.Text("frame_id")==candidate)).Take(3).ToArray();frames.SelectedItems.Clear();foreach(var id in eligible)frames.SelectedItems.Add(frameChoices[id]);Check(frames.SelectedItems.Count==3,"in-process selection, NOT physical Ctrl/Shift");BatchNormal();WaitHotfix();Check(eligible.All(id=>s.Find(id).Text("state")=="normal"),"UI batch command persisted");UndoNormalBatch();WaitHotfix();Check(eligible.All(id=>s.Find(id).Text("state")=="unannotated"),"UI undo persisted");});
   test("full-and-delta-export-verify-all-assets-roundtrip",()=>{var baseline=Codec.Clone(s.Data);string full=Path.Combine(output,"full.ids");Packages.Export(s,full,null);var imported=Packages.Import(full,Path.Combine(output,"receiver"));Check(Codec.Fingerprint(s.Data)==Codec.Fingerprint(imported.Data),"full import");string id=empty().Last();s.ReviewCurrent(id,"unknown","unknown","hotfix");string delta=Path.Combine(output,"delta.ids");Packages.Export(s,delta,baseline);Packages.Import(delta,imported.Root);Check(Codec.Fingerprint(s.Data)==Codec.Fingerprint(new Store(imported.Root).Data),"delta import");});
   test("changed-current-image-rejected-and-export-full-hash-protects",()=>{string id=empty().Last(),path=Rules.SafePath(root,s.Find(id).Text("asset_path"));byte[] original=File.ReadAllBytes(path);string before=Codec.Fingerprint(s.Data);File.AppendAllText(path,"changed");try{bool rejected=false;try{s.ReviewCurrent(id,"normal","confirmed","hotfix");}catch(InvalidDataException){rejected=true;}Check(rejected&&before==Codec.Fingerprint(s.Data),"changed image rejected");rejected=false;try{Packages.Export(s,Path.Combine(output,"bad.ids"),null);}catch(InvalidDataException){rejected=true;}Check(rejected&&!File.Exists(Path.Combine(output,"bad.ids")),"full export fails closed");}finally{File.WriteAllBytes(path,original);}});
   test("cancel-after-temp-flush-rolls-back",()=>{string id=empty().Last(),before=Codec.Fingerprint(s.Data);bool cancelled=false;Work.Configure(()=>false,message=>{if(message=="HOTFIX_COMMIT_PRE_REPLACE")throw new OperationCanceledException();});try{s.ReviewCurrent(id,"normal","confirmed","cancel-after-flush");}catch(OperationCanceledException){cancelled=true;}finally{Work.Configure(null,null);}Check(cancelled&&before==Codec.Fingerprint(s.Data)&&before==Codec.Fingerprint(reopen().Data),"atomic cancellation after actual write");Check(Directory.GetFiles(root,"*.tmp").Length==0,"failed temp cleaned");});
   test("ui-save-in-pending-filter-advances-without-rebuild",()=>{Use(s);Navigate("标注与审核");frameStateFilter.SelectedIndex=1;var eligible=empty().Where(candidate=>!s.Data.entities.Any(e=>e.kind=="Annotation"&&e.Text("frame_id")==candidate)).ToArray();frames.SelectedItem=frameChoices[eligible[0]];string id=frame.id,next=NextVisibleFrame(id);var source=frames.ItemsSource;saveAdvanceCommand.Execute(null,this);WaitHotfix();Check(s.Find(id).Text("state")=="normal"&&!visibleFrames.Contains(frameChoices[id]),"saved row removed from pending filter");Check(Object.ReferenceEquals(source,frames.ItemsSource)&&frame.id==next,"same collection / exact filtered next UUID");Check(frameSummary.Text.StartsWith("已确认 0 /"),"confirmed count follows filtered list");frameStateFilter.SelectedIndex=2;frames.SelectedItem=frameChoices[id];saveAdvanceCommand.Execute(null,this);WaitHotfix();Check(s.Find(id).revision>=3,"confirmed frame reopened and edited");frameStateFilter.SelectedIndex=0;});
   test("ui-write-denial-retains-review-draft",()=>{Use(s);Navigate("标注与审核");frameStateFilter.SelectedIndex=0;string id=frame.id;state.SelectedIndex=3;review.SelectedIndex=2;bool failedAsExpected=false;using(var hold=new FileStream(Path.Combine(root,".write.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){SaveAndAdvance(false,true);try{WaitHotfix();}catch(InvalidOperationException){failedAsExpected=true;}}Check(failedAsExpected&&!busy&&status.Text.StartsWith("操作失败")&&frame.id==id&&state.SelectedIndex==3&&review.SelectedIndex==2&&reviewEdited,"actual write denial retains draft and frame");reviewEdited=false;ShowFrame();});
   test("legacy-pretty-json-reopen-local-commit",()=>{string dir=Path.Combine(output,"legacy-format");var legacy=Fixture(dir,2);string manifest=File.ReadAllText(legacy.Manifest);File.WriteAllText(legacy.Manifest," \n"+manifest+"\n");legacy=new Store(dir);string id=legacy.Data.entities.First(e=>e.kind=="Frame").id;legacy.ReviewCurrent(id,"normal","confirmed","legacy");Check(Codec.Fingerprint(legacy.Data)==Codec.Fingerprint(new Store(dir).Data),"whitespace legacy normalizes once on open");});
   test("actual-two-process-conflict-rejects-stale-session",()=>{string ready=Path.Combine(output,"writer-ready.txt");var stale=reopen();using(var child=StartHotfixChild(root,ready,"write")){Check(child.WaitForExit(15000)&&child.ExitCode==0,"owned child committed");}string disk=Codec.Fingerprint(reopen().Data);bool rejected=false;try{stale.ReviewCurrent(empty().Last(),"normal","confirmed","stale-parent");}catch(IOException){rejected=true;}Check(rejected&&disk==Codec.Fingerprint(reopen().Data),"actual independent process conflict rejected");s=reopen();});
   foreach(string mode in new[]{"pre","post"})test("fast-commit-hard-exit-"+mode+"-atomic-recovery",()=>{string dir=Path.Combine(output,"crash-"+mode),ready=Path.Combine(output,"crash-"+mode+"-ready.txt");var fixture=Fixture(dir,6);string before=Codec.Fingerprint(fixture.Data);using(var child=StartHotfixChild(dir,ready,mode)){try{var clock=System.Diagnostics.Stopwatch.StartNew();while(!File.Exists(ready)&&!child.HasExited&&clock.ElapsedMilliseconds<15000)System.Threading.Thread.Sleep(20);Check(File.Exists(ready)&&!child.HasExited,"own child paused at actual commit stage");child.Kill();Check(child.WaitForExit(5000),"own child terminated");}finally{if(!child.HasExited){child.Kill();child.WaitForExit(5000);}}}var recovered=new Store(dir);Rules.VerifyAssets(recovered.Data,dir);Check(Codec.Fingerprint(recovered.Data)==(mode=="pre"?before:File.ReadAllText(ready)),"old or new complete document recovered");if(mode=="pre")Check(Directory.GetFiles(dir,"*.tmp").Length==1,"uncommitted temp ignored");recovered.ReviewCurrent(recovered.Data.entities.First(e=>e.kind=="Frame").id,"normal","confirmed","recovery");Check(Codec.Fingerprint(recovered.Data)==Codec.Fingerprint(new Store(dir).Data),"lock released and next commit valid");});
   test("cache-budget-and-no-physical-input-claim",()=>{foreach(var f in orderedFrames)GetBitmap(f);Check(bitmapBytes<=BitmapBudget&&bitmapLru.Count<=12,"bounded image LRU");});
   ticker.Stop();return failed==0?0:1;
  }
 }
}
